<?php namespace App\Models;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;class ProgressReportSubject extends Model{use HasFactory;protected $table="progress_report_subjects";protected $fillable=["progress_report_id","subject_name","marks_obtained","max_marks","grade","remarks"];protected $casts=["marks_obtained"=>"decimal:2","max_marks"=>"decimal:2"];public function progressReport(){return $this->belongsTo(ProgressReport::class);}}